const ELEMENT_PROP_KEYS = new Set(["theme","text","focus","cue","stagger","hold","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  text: "One person wrote this entire launch video over a single lunch break.",
  focus: "One person",
  cue: "Read that again.",
  stagger: 3,
  hold: 8,
  fontFamily: "Outfit",
  scale: 1,
  delay: 0,
  speed: 1,
};

type DoubleTakeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof DoubleTakeBase>;

const DoubleTakeInner = forwardRef<
  HTMLDivElement,
  DoubleTakeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<DoubleTake>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <DoubleTakeBase
          {...(componentProps as unknown as ComponentProps<typeof DoubleTakeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const DoubleTake = Interactive.withSchema({
  Component: DoubleTakeInner,
  componentName: "<DoubleTake>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
